impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for Vector<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for Vector<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic Vector" } else { "Vector" });
        for (b, c) in <Vector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

// SAFETY: `Arr<X>` is `[X; 6]`, the layout `gx::FlatKind` promises.
unsafe impl<O: gx::Orientation> gx::FlatKind for Vector<(), f64, O> {}

impl<O: gx::Orientation> gx::Kind for Vector<(), f64, O> {
    const N: usize = 6;
    const NAME: &'static str = "Vector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e3", "e4", "eo", "ei"];
    type Arr<X: gx::Elem> = [X; 6];
    type Mv<S: gx::Slots, T: gx::Coef> = Vector<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = false;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 6] {
        [f(0), f(1), f(2), f(3), f(4), f(5)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 6], mut f: impl FnMut(&X) -> Y) -> [Y; 6] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 6],
        b: &[Y; 6],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 6] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5])]
    }
}

