#[doc = "A quadvector."]
///
/// Blades, in coefficient order: `[e1234, e234o, e314o, e124o, e123o, e234i, e314i, e124i, e123i, e23oi, e31oi, e12oi, e41oi, e42oi, e43oi]`.
///
/// `S` lists the open slots: `Quadvector` (that is, `Quadvector<()>`) is a value, `Quadvector<(A,)>` a
/// linear map from `A`, `Quadvector<(A, B)>` a bilinear map. `T` is the coefficient type. `O` is
/// the orientation of the output, extrinsic by default (ADR-051).
#[repr(C)]
pub struct Quadvector<S: gx::Slots = (), T: gx::Coef = f64, O: gx::Orientation = gx::Extrinsic> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 15],
    o: core::marker::PhantomData<O>,
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Clone for Quadvector<S, T, O> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Copy for Quadvector<S, T, O> {}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for Quadvector<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for Quadvector<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic Quadvector" } else { "Quadvector" });
        for (b, c) in <Quadvector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

// SAFETY: `Arr<X>` is `[X; 15]`, the layout `gx::FlatKind` promises.
unsafe impl<O: gx::Orientation> gx::FlatKind for Quadvector<(), f64, O> {}

impl<O: gx::Orientation> gx::Kind for Quadvector<(), f64, O> {
    const N: usize = 15;
    const NAME: &'static str = "Quadvector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1234", "e234o", "e314o", "e124o", "e123o", "e234i", "e314i", "e124i", "e123i", "e23oi", "e31oi", "e12oi", "e41oi", "e42oi", "e43oi"];
    type Arr<X: gx::Elem> = [X; 15];
    type Mv<S: gx::Slots, T: gx::Coef> = Quadvector<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = false;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 15] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 15], mut f: impl FnMut(&X) -> Y) -> [Y; 15] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 15],
        b: &[Y; 15],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 15] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14])]
    }
}

