#[doc = "A quintvector (dual to a vector)."]
///
/// Blades, in coefficient order: `[e234oi, e314oi, e124oi, e123oi, e1234o, e1234i]`.
///
/// `S` lists the open slots: `Quintvector` (that is, `Quintvector<()>`) is a value, `Quintvector<(A,)>` a
/// linear map from `A`, `Quintvector<(A, B)>` a bilinear map. `T` is the coefficient type. `O` is
/// the orientation of the output, extrinsic by default (ADR-051).
#[repr(C)]
pub struct Quintvector<S: gx::Slots = (), T: gx::Coef = f64, O: gx::Orientation = gx::Extrinsic> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 6],
    o: core::marker::PhantomData<O>,
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Clone for Quintvector<S, T, O> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Copy for Quintvector<S, T, O> {}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for Quintvector<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for Quintvector<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic Quintvector" } else { "Quintvector" });
        for (b, c) in <Quintvector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

// SAFETY: `Arr<X>` is `[X; 6]`, the layout `gx::FlatKind` promises.
unsafe impl<O: gx::Orientation> gx::FlatKind for Quintvector<(), f64, O> {}

impl<O: gx::Orientation> gx::Kind for Quintvector<(), f64, O> {
    const N: usize = 6;
    const NAME: &'static str = "Quintvector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e234oi", "e314oi", "e124oi", "e123oi", "e1234o", "e1234i"];
    type Arr<X: gx::Elem> = [X; 6];
    type Mv<S: gx::Slots, T: gx::Coef> = Quintvector<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = false;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 6] {
        [f(0), f(1), f(2), f(3), f(4), f(5)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 6], mut f: impl FnMut(&X) -> Y) -> [Y; 6] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 6],
        b: &[Y; 6],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 6] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5])]
    }
}

